import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { getParentRelationshipHandler } from "../handlers/getParentRelationshipHandler";
import type { ApiError } from "../runtime/client";
import type { TeamPartition } from "../types/TeamPartition";

type Data = Awaited<ReturnType<typeof getParentRelationshipHandler>>;

export function useGetParentRelationship(
  teamPk: TeamPartition,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["getParentRelationship", teamPk],
    queryFn: () => getParentRelationshipHandler(teamPk),
    ...options,
  });
}
